// Event ورودی WordPress باید سبک باشد: فقط شناسه پست و نوع Event.
// محتوای کامل بعداً از WordPress REST API واکشی می‌شود.
const crypto = require('crypto');
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body ?? req;

// Header رسمی و تنها مسیر Auth این پروژه (Fix #7):
// x-omid90-webhook-secret که در پروژه قبلی استفاده می‌شد حذف شد چون این پروژه
// هیچ نیاز Backward-Compatibility با آن سیستم ندارد و وجودش فقط سطح حمله را
// بدون سود مستند شده افزایش می‌داد.
const secretHeader = headers['x-wp-webhook-secret'];
const secret = typeof secretHeader === 'string' ? secretHeader : '';
const expectedRaw = $vars.WORDPRESS_WEBHOOK_SECRET;
const expected = typeof expectedRaw === 'string' ? expectedRaw : '';

// Fix #6: مقایسه Timing-Safe به‌جای === ساده.
// crypto.timingSafeEqual نیاز دارد طول دو Buffer برابر باشد، وگرنه Throw می‌کند؛
// این خودش می‌تواند یک Timing Side-channel کوچک (طول) باشد که غیرقابل‌اجتناب است
// چون طول رشته را نمی‌توان پنهان کرد، اما محتوای رشته دیگر با مقایسه کاراکتر-به-کاراکتر
// زودهنگام لو نمی‌رود. اگر یکی از دو مقدار خالی باشد، بدون فراخوانی crypto رد می‌شود
// (Secret خالی هرگز نباید معتبر باشد، صرف‌نظر از پیاده‌سازی).
function timingSafeStringEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length === 0 || b.length === 0) return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    // برای جلوگیری از خروج زودهنگام، همچنان یک مقایسه با طول برابر (خودِ bufA) انجام می‌دهیم
    // تا زمان اجرا مستقل از اینکه bufB کوتاه‌تر/بلندتر است تا حد ممکن یکنواخت بماند.
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

const authorized = Boolean(expected) && timingSafeStringEqual(secret, expected);

const allowedTypes = new Set(['post.published','post.updated']);
const eventType = String(body.eventType || body.event || '').trim();
const postId = Number(body.postId || body.post_id || body.ID || 0);

const payloadValid = allowedTypes.has(eventType) && Number.isInteger(postId) && postId > 0;
const valid = authorized && payloadValid;

// Fix #15: مسیر پاسخ باید بین «احراز هویت نامعتبر» (401) و «Payload نامعتبر با Secret درست» (422)
// تفکیک شود. outcome یکی از سه مقدار زیر است: 'ok' | 'unauthorized' | 'invalid_payload'
let outcome;
if (!authorized) outcome = 'unauthorized';
else if (!payloadValid) outcome = 'invalid_payload';
else outcome = 'ok';

return [{json:{
  authorized, payloadValid, valid, outcome, eventType, postId,
  receivedAt: new Date().toISOString(),
  rawEvent: body
}}];

// نرمال‌سازی Post خام WordPress به مدل استاندارد Article.
// هیچ Adapter پایین‌دستی نباید مستقیماً به ساختار خام WordPress وابسته باشد.
const wp = $input.first().json.body || $input.first().json;
const meta = $('اعتبارسنجی Webhook').first().json;

function stripHtml(html){
  return String(html||'')
    .replace(/<[^>]*>/g,' ')
    .replace(/&nbsp;/g,' ')
    .replace(/&amp;/g,'&')
    .replace(/&#8217;|&#039;/g,"'")
    .replace(/&#8220;|&#8221;|&quot;/g,'"')
    .replace(/\s+/g,' ')
    .trim();
}

const embedded = wp._embedded || {};
const terms = embedded['wp:term'] || [];
const categories = (terms[0]||[]).map(t=>t.name).filter(Boolean);
const tags = (terms[1]||[]).map(t=>t.name).filter(Boolean);
const author = (embedded.author && embedded.author[0] && embedded.author[0].name) || '';
const featuredMedia = embedded['wp:featuredmedia'] && embedded['wp:featuredmedia'][0];
const featuredImage = (featuredMedia && (featuredMedia.source_url || (featuredMedia.media_details && featuredMedia.media_details.sizes && featuredMedia.media_details.sizes.full && featuredMedia.media_details.sizes.full.source_url))) || null;

const article = {
  postId: wp.id,
  title: stripHtml(wp.title && wp.title.rendered),
  content: (wp.content && wp.content.rendered) || '',
  contentText: stripHtml(wp.content && wp.content.rendered),
  excerpt: stripHtml(wp.excerpt && wp.excerpt.rendered),
  url: wp.link,
  featuredImage,
  categories,
  tags,
  author,
  publishedAt: wp.date_gmt ? wp.date_gmt + 'Z' : wp.date,
  modifiedAt: wp.modified_gmt ? wp.modified_gmt + 'Z' : wp.modified
};

// eventId پایدار بر اساس postId + modifiedAt: هر بار محتوای پست واقعاً تغییر کند، Event جدید مجاز است؛
// تکرار همان نسخه (همان modifiedAt) به‌عنوان Duplicate رد می‌شود.
const eventId = `wp:${article.postId}:${article.modifiedAt}`;

return [{json:{
  eventId,
  eventType: meta.eventType,
  entityId: String(article.postId),
  publicationVersion: article.modifiedAt,
  priority: 50,
  receivedAt: meta.receivedAt,
  article
}}];

const event = $('Normalize Article').first().json;
const rows = $input.all().map(i=>i.json).filter(Boolean);
const duplicate = rows.some(r => String(r.event_id || r.eventId) === event.eventId);
return [{json:{...event, duplicate}}];

const e = $('تشخیص تکراری').first().json;
const activeRaw = $vars.ACTIVE_PLATFORMS || 'telegram,bale,eitaa,rubika,x,linkedin';
const platforms = activeRaw.split(',').map(s=>s.trim()).filter(Boolean);

return platforms.map(platform => ({json:{
  job_id: `${e.article.postId}:${platform}:${e.publicationVersion}`,
  event_id: e.eventId,
  event_type: e.eventType,
  platform,
  status: 'pending',
  priority: e.priority,
  attempts: 0,
  max_attempts: 5,
  next_attempt_at: new Date().toISOString(),
  article_json: JSON.stringify(e.article),
  created_at: new Date().toISOString()
}}));

// Fix #1: نرمال‌سازی خروجی HTTP Request (که اکنون fullResponse=true دارد) به شکل یکنواخت
// {statusCode, body} برای Nodeهای بعدی، مستقل از این‌که n8n دقیقاً چه شکلی برمی‌گرداند.
const raw = $input.first().json;
const statusCode = Number(raw.statusCode ?? (raw.body && raw.body.statusCode) ?? 599);
const body = raw.body !== undefined ? raw.body : raw;
return [{json:{statusCode, body}}];

// Fix #10: راهکار عملی برای Race Condition در Dedup سطح Event.
// اگر Insert به دلیل نقض UNIQUE(event_id) با خطا مواجه شود و Node با onError=continueRegularOutput پیکربندی شده باشد،
// n8n معمولاً همان Item ورودی را همراه با یک فیلد error در خروجی برمی‌گرداند (شکل دقیق بسته به نسخه n8n متفاوت است؛
// این کد چند شکل رایج را پوشش می‌دهد). اگر خطای Insert تشخیص داده شود، همان رویداد را «تکراری» در نظر می‌گیریم
// (چون تنها دلیل معقول شکست Insert روی event_id یکتا، وجود قبلی همان ردیف در یک اجرای هم‌زمان دیگر است) و به‌جای
// ادامه، مسیر Duplicate را دنبال می‌کنیم — نه اینکه فرض کنیم Insert همیشه موفق بوده (باگ قبلی).
const item = $input.first().json;
const event = $('تشخیص تکراری').first().json;

const looksLikeError = Boolean(
  item.error ||
  item.json?.error ||
  (typeof item.message === 'string' && /unique|duplicate|constraint/i.test(item.message))
);

return [{json:{...event, insertRaceDetected: looksLikeError}}];

// Fix #3: respondToWebhook فقط باید یک‌بار و با یک Item اجرا شود.
// «ساخت Publication Job برای هر پلتفرم» به تعداد پلتفرم‌های فعال Item جدا تولید می‌کند؛
// این Node همه آن Itemها را جمع می‌کند و یک خروجی واحد می‌سازد.
const items = $input.all();
const jobsCreated = items.length;
const eventId = items[0]?.json?.event_id || $('تشخیص تکراری').first().json.eventId;
return [{json:{ accepted: true, eventId, jobsCreated }}];
